//! Sampled-value parity with motion 12.43.0.
//!
//! `tests/fixtures/ease-samples.txt` is generated by `scripts/gen-fixtures.sh`
//! from the shipped `motion-utils/dist/es/easing/cubic-bezier.mjs`, so this test
//! compares the Rust port against the real implementation of the library beUI
//! animates with, not against a hand-written expectation.

use beui_core::ease;

const FIXTURE: &str = include_str!("fixtures/ease-samples.txt");

/// Values are produced by the same f64 operations in both languages, so the
/// only allowed difference is the last bit of the printed representation.
const TOLERANCE: f64 = 1e-15;

fn samples<'a>() -> Vec<(&'a str, Vec<(f64, f64)>)> {
    let mut curves: Vec<(&str, Vec<(f64, f64)>)> = Vec::new();
    for line in FIXTURE.lines() {
        if let Some(name) = line.strip_prefix('[').and_then(|l| l.strip_suffix(']')) {
            curves.push((name, Vec::new()));
            continue;
        }
        if line.trim().is_empty() {
            continue;
        }
        let (x, y) = line.split_once('\t').expect("x\ty");
        curves
            .last_mut()
            .expect("sample before curve header")
            .1
            .push((x.parse().unwrap(), y.parse().unwrap()));
    }
    curves
}

#[test]
fn cubic_bezier_matches_motion() {
    let curves = samples();
    assert_eq!(
        curves.iter().map(|(n, _)| *n).collect::<Vec<_>>(),
        ["ease_out", "ease_in_out", "ease_drawer"]
    );

    for (name, points) in curves {
        let f = match name {
            "ease_out" => ease::ease_out,
            "ease_in_out" => ease::ease_in_out,
            _ => ease::ease_drawer,
        };
        assert!(points.len() > 100, "{name}: only {} samples", points.len());
        for (x, expected) in points {
            let actual = f(x);
            assert!(
                (actual - expected).abs() <= TOLERANCE,
                "{name}({x}) = {actual}, motion gives {expected}"
            );
        }
    }
}

#[test]
fn linear_gradient_is_the_identity_like_motion() {
    // motion returns `noop` when `mX1 === mY1 && mX2 === mY2`.
    for step in 0..=10 {
        let x = step as f64 / 10.0;
        assert_eq!(ease::cubic_bezier_value(0.42, 0.42, 0.58, 0.58, x), x);
    }
}

#[test]
fn easing_adapters_use_the_easer_convention() {
    // easer calls `f(t, b, c, d) = b + c * f(t / d)`.
    assert_eq!(ease::ease_out_easer(0.0, 10.0, 90.0, 1.0), 10.0);
    assert_eq!(ease::ease_out_easer(1.0, 10.0, 90.0, 1.0), 100.0);
    let mid = ease::ease_out_easer(0.5, 0.0, 1.0, 1.0);
    assert!((mid - ease::ease_out(0.5) as f32).abs() < 1e-7);
}
